      const view = (cur) => [
        { t: "array", label: "原链表", items: v.map((x, i) => ({ v: x, cls: cur >= 0 && (i === cur || i === cur + 1) ? "a" : done.has(i) ? "k" : calls.some((c) => c === i || c + 1 === i) ? "e" : "" })), idx: false },
